import * as OurTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of First", () => {
  const theFirst =
    TestCommonJsonization.loadMinimalFirst();

  expect(
    OurTypes.isItem(theFirst)
  ).toStrictEqual(true);
  expect(
    OurTypes.asItem(theFirst)
  ).toStrictEqual(theFirst);

  expect(
    OurTypes.isFirst(theFirst)
  ).toStrictEqual(true);
  expect(
    OurTypes.asFirst(theFirst)
  ).toStrictEqual(theFirst);

  expect(
    OurTypes.isSecond(theFirst)
  ).toStrictEqual(false);
  expect(
    OurTypes.asSecond(theFirst)
  ).toBeNull();
});

test("casts over an instance of Second", () => {
  const theSecond =
    TestCommonJsonization.loadMinimalSecond();

  expect(
    OurTypes.isItem(theSecond)
  ).toStrictEqual(true);
  expect(
    OurTypes.asItem(theSecond)
  ).toStrictEqual(theSecond);

  expect(
    OurTypes.isFirst(theSecond)
  ).toStrictEqual(false);
  expect(
    OurTypes.asFirst(theSecond)
  ).toBeNull();

  expect(
    OurTypes.isSecond(theSecond)
  ).toStrictEqual(true);
  expect(
    OurTypes.asSecond(theSecond)
  ).toStrictEqual(theSecond);
});

